from pathlib import Path

p=Path("src/UnifiedApp.tsx")
s=p.read_text()
if 'import "./pilotHome.css";' not in s:
    raise SystemExit("pilotHome import not found")
if 'const AMIODARONE_VIAL_IMAGE=' not in s:
    s=s.replace('import "./pilotHome.css";', 'import "./pilotHome.css";\n\nconst AMIODARONE_VIAL_IMAGE=\'data:image/webp;base64,\';', 1)
old='<span className={`pilot-vial ${id==="adenosine"?"has-photo":""}`} aria-hidden="true">{id==="adenosine"?<img src="/medications/adenosine-vial.webp" alt=""/>:<><i/><b>{id==="midazolam"?"VERSED":def.name.toUpperCase()}</b><small>REFERENCE</small></>}</span>'
new='<span className={`pilot-vial ${id==="adenosine"||id==="amiodarone"?"has-photo":""}`} aria-hidden="true">{id==="adenosine"?<img src="/medications/adenosine-vial.webp" alt=""/>:id==="amiodarone"?<img src={AMIODARONE_VIAL_IMAGE} alt=""/>:<><i/><b>{id==="midazolam"?"VERSED":def.name.toUpperCase()}</b><small>REFERENCE</small></>}</span>'
if old not in s:
    raise SystemExit("vial renderer anchor not found")
s=s.replace(old,new,1)
p.write_text(s)
print("Amiodarone isolated vial photo added to first-page card")
